
"""Persist hedge obligations generated by Antivist fills."""

import sqlite3

from dataclasses import dataclass
from decimal import Decimal
from pathlib import Path

from albridge.risk.hedge_obligation import HedgeObligation


@dataclass(frozen=True)
class StoredHedgeObligation:
    execution_id: int
    leg_index: int
    client_order_id: str
    venue: str
    instrument_id: str | None
    outcome: str
    execution_side: str
    pm_price: Decimal
    quantity: Decimal
    status: str
    hedged_quantity: Decimal


class ObligationRegistry:
    """Persist individual hedge obligations across restarts."""

    def __init__(self, database_path: str | Path):
        self.database_path = str(database_path)

        with sqlite3.connect(self.database_path) as connection:
            connection.execute("""
                CREATE TABLE IF NOT EXISTS hedge_obligations (
                    execution_id INTEGER NOT NULL,
                    leg_index INTEGER NOT NULL,
                    client_order_id TEXT NOT NULL,
                    venue TEXT NOT NULL,
                    instrument_id TEXT,
                    outcome TEXT NOT NULL,
                    execution_side TEXT NOT NULL,
                    pm_price TEXT NOT NULL,
                    quantity TEXT NOT NULL,
                    status TEXT NOT NULL,
                    PRIMARY KEY (execution_id, leg_index)
                )
            """)

        with sqlite3.connect(self.database_path) as connection:
            connection.execute("""
                CREATE TABLE IF NOT EXISTS external_hedge_fills (
                    venue TEXT NOT NULL,
                    external_execution_id TEXT NOT NULL,
                    execution_id INTEGER NOT NULL,
                    leg_index INTEGER NOT NULL,
                    quantity TEXT NOT NULL,
                    PRIMARY KEY (venue, external_execution_id)
                )
            """)

        self.initialize_hedged_quantity()

    def register(
        self,
        *,
        obligations: tuple[HedgeObligation, ...],
    ) -> None:
        """
        Register obligations idempotently.

        Initially all obligations are PENDING.
        No external hedge is executed.
        """

        with sqlite3.connect(self.database_path) as connection:
            for index, obligation in enumerate(obligations):
                connection.execute(
                    """
                    INSERT OR IGNORE INTO hedge_obligations (
                        execution_id,
                        leg_index,
                        client_order_id,
                        venue,
                        instrument_id,
                        outcome,
                        execution_side,
                        pm_price,
                        quantity,
                        status
                    )
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                    """,
                    (
                        obligation.execution_id,
                        index,
                        obligation.client_order_id,
                        obligation.venue,
                        obligation.instrument_id,
                        obligation.outcome,
                        obligation.execution_side,
                        str(obligation.pm_price),
                        str(obligation.quantity),
                        "PENDING",
                    ),
                )

    def get_pending(self) -> tuple[StoredHedgeObligation, ...]:
        """Return hedge obligations awaiting execution."""

        with sqlite3.connect(self.database_path) as connection:
            rows = connection.execute(
                """
                SELECT
                    execution_id,
                    leg_index,
                    client_order_id,
                    venue,
                    instrument_id,
                    outcome,
                    execution_side,
                    pm_price,
                    quantity,
                    status,
                    hedged_quantity
                FROM hedge_obligations
                WHERE status IN ('PENDING', 'PARTIALLY_HEDGED')
                ORDER BY execution_id, leg_index
                """
            ).fetchall()

        return tuple(
            StoredHedgeObligation(
                execution_id=row[0],
                leg_index=row[1],
                client_order_id=row[2],
                venue=row[3],
                instrument_id=row[4],
                outcome=row[5],
                execution_side=row[6],
                pm_price=Decimal(row[7]),
                quantity=Decimal(row[8]),
                status=row[9],
                hedged_quantity=Decimal(row[10]),
            )
            for row in rows
        )

    def initialize_hedged_quantity(self) -> None:
        """
        Add hedged quantity storage to an existing database.

        Safe to call repeatedly.
        """

        with sqlite3.connect(self.database_path) as connection:
            columns = {
                row[1]
                for row in connection.execute(
                    "PRAGMA table_info(hedge_obligations)"
                )
            }

            if "hedged_quantity" not in columns:
                connection.execute(
                    """
                    ALTER TABLE hedge_obligations
                    ADD COLUMN hedged_quantity TEXT NOT NULL DEFAULT '0'
                    """
                )


    def record_hedge_fill(
        self,
        *,
        execution_id: int,
        leg_index: int,
        filled_quantity: Decimal,
    ) -> None:
        """
        Record confirmed external hedge quantity.

        This method must only receive actual confirmed hedge fills.
        Never call it when merely submitting an external hedge order.
        """

        if (
            not filled_quantity.is_finite()
            or filled_quantity <= 0
        ):
            raise ValueError("Invalid hedge fill quantity")

        with sqlite3.connect(self.database_path) as connection:
            connection.execute("BEGIN IMMEDIATE")

            row = connection.execute(
                """
                SELECT quantity, hedged_quantity, status
                FROM hedge_obligations
                WHERE execution_id = ? AND leg_index = ?
                """,
                (execution_id, leg_index),
            ).fetchone()

            if row is None:
                raise ValueError("Unknown hedge obligation")

            total_quantity = Decimal(row[0])
            already_hedged = Decimal(row[1])

            new_hedged = already_hedged + filled_quantity

            if new_hedged > total_quantity:
                raise ValueError("Hedge quantity exceeds obligation")

            status = (
                "HEDGED"
                if new_hedged == total_quantity
                else "PARTIALLY_HEDGED"
            )

            connection.execute(
                """
                UPDATE hedge_obligations
                SET hedged_quantity = ?, status = ?
                WHERE execution_id = ? AND leg_index = ?
                """,
                (
                    str(new_hedged),
                    status,
                    execution_id,
                    leg_index,
                ),
            )

    def record_external_fill(
        self,
        *,
        venue: str,
        external_execution_id: str,
        execution_id: int,
        leg_index: int,
        filled_quantity: Decimal,
    ) -> bool:
        """
        Record a confirmed external hedge execution exactly once.

        Return True for a new execution, False for a duplicate.
        """

        if not venue or not external_execution_id:
            raise ValueError("Missing external execution identity")

        if (
            not filled_quantity.is_finite()
            or filled_quantity <= 0
        ):
            raise ValueError("Invalid fill quantity")

        with sqlite3.connect(self.database_path) as connection:
            connection.execute("BEGIN IMMEDIATE")

            existing = connection.execute(
                """
                SELECT execution_id, leg_index, quantity
                FROM external_hedge_fills
                WHERE venue = ? AND external_execution_id = ?
                """,
                (venue, external_execution_id),
            ).fetchone()

            if existing is not None:
                if existing != (
                    execution_id,
                    leg_index,
                    str(filled_quantity),
                ):
                    raise ValueError("Conflicting external execution")
                return False

            row = connection.execute(
                """
                SELECT venue, quantity, hedged_quantity
                FROM hedge_obligations
                WHERE execution_id = ? AND leg_index = ?
                """,
                (execution_id, leg_index),
            ).fetchone()

            if row is None:
                raise ValueError("Unknown hedge obligation")

            if row[0] != venue:
                raise ValueError("Hedge venue mismatch")

            total = Decimal(row[1])
            hedged = Decimal(row[2])
            updated = hedged + filled_quantity

            if updated > total:
                raise ValueError("Hedge exceeds obligation")

            status = (
                "HEDGED"
                if updated == total
                else "PARTIALLY_HEDGED"
            )

            connection.execute(
                """
                INSERT INTO external_hedge_fills (
                    venue, external_execution_id,
                    execution_id, leg_index, quantity
                )
                VALUES (?, ?, ?, ?, ?)
                """,
                (
                    venue,
                    external_execution_id,
                    execution_id,
                    leg_index,
                    str(filled_quantity),
                ),
            )

            connection.execute(
                """
                UPDATE hedge_obligations
                SET hedged_quantity = ?, status = ?
                WHERE execution_id = ? AND leg_index = ?
                """,
                (str(updated), status, execution_id, leg_index),
            )

        return True